import networkx as nx

g = Graph()
for i in range(19):
    g.add_node(i)

# Add edges to the graph such that every vertex has degree between 4 and 7
for i in range(19):
    for j in range(i+1, 19):
        if len(list(g.neighbors(i))) < 7 and len(list(g.neighbors(j))) < 7:
            g.add_edge(i, j)

# Check if the girth of the graph is at least 8
if girth(g) >= 8:
    print("SATISFIABLE")
    print(list(g.edges))
